mapper.select:
INSERT INTO ingest_run_item (run_id, item_key, item_kind)
SELECT #{runId}, #{itemKey}, #{itemKind}
WHERE EXISTS (
    SELECT 1
    FROM ingest_run
    WHERE id = #{runId}
      AND status = 'RUNNING'
      AND attempt = #{attempt}
      AND lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)
)
ON CONFLICT (run_id, item_key) DO UPDATE
SET updated_at = now()
RETURNING
